    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (0)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        uint b0 = address(c).balance;
        bool r1;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { r1 = true; } else { r1 = false; }
        uint b1 = address(c).balance;
        bool r2;
        c.go{value: 0}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { r2 = true; } else { r2 = false; }
        uint b2 = address(c).balance;
        assert(
            (r1 ? b1 == b0 + amount : b1 == 0) &&
            (r2 ? b2 == b1 : b2 == 0)
        );
    }
    receive() external payable {}
}

